/// Переменные хоста, которые видят дочерние процессы агента
/// (`agent-core-architecture` §4.5, шаг 1; ENV-6).
///
/// Почему отдельный файл: команды `exec` (`LocalExecutionEnv`) и stdio-серверы
/// MCP (`StdioProcessTransport`) строят окружение по одному allowlist —
/// остальное окружение хоста (токены, ключи облаков) процессу не видно.
///
/// Как использовать: брать значения этих имён из окружения хоста; всё, что
/// сверх них, процесс получает явно (`env` команды или сервера).
const hostEnvironmentAllowlist = [
  'PATH',
  'HOME',
  'USER',
  'LANG',
  'LC_ALL',
  'TMPDIR',
  'SHELL',
];
